// Generated by AI (UnitTest MCP)
//! Exact signed bytes for EvidenceService requests.
//!
//! Evidence is not raw terminal output or a source blob. Its signer binds the
//! task, closed evidence kind, bounded reference, SHA-256 digest, observation
//! time, and agent session so an in-flight request cannot be retargeted.

use crate::signing_bytes::push_field;
use crate::v1;

/// Domain separation for EvidenceService request signatures.
pub const EVIDENCE_DOMAIN: &[u8] = b"mindleak.ackplane.v1.evidence\0";

/// Which EvidenceService operation an authentication authorizes.
#[derive(Debug, Clone, Copy)]
pub enum EvidenceOperation<'a> {
    Record {
        task_id: &'a str,
        evidence_kind: i32,
        source_ref: &'a str,
        content_digest: &'a [u8],
        observed_at: &'a str,
        reported_agent_session_id: &'a str,
        idempotency_key: &'a str,
        reported_constitution_version: &'a str,
    },
    List {
        task_id: &'a str,
        limit: u32,
        page_before_recorded_at: Option<&'a str>,
        page_before_evidence_id: Option<&'a str>,
    },
    RecordConformance {
        task_id: &'a str,
        evidence_id: &'a str,
        verdict: i32,
        finding_count: u32,
        findings_digest: &'a [u8],
        finding_codes: &'a [i32],
        reported_checked_at: &'a str,
        idempotency_key: &'a str,
        reported_constitution_version: &'a str,
    },
    ListConformance {
        task_id: &'a str,
        limit: u32,
        page_before_recorded_at: Option<&'a str>,
        page_before_conformance_id: Option<&'a str>,
    },
}

impl EvidenceOperation<'_> {
    fn tag(&self) -> &'static str {
        match self {
            Self::Record { .. } => "record",
            Self::List { .. } => "list",
            Self::RecordConformance { .. } => "record_conformance",
            Self::ListConformance { .. } => "list_conformance",
        }
    }

    fn push_fields(&self, bytes: &mut Vec<u8>) {
        push_field(bytes, self.tag().as_bytes());
        match self {
            Self::Record {
                task_id,
                evidence_kind,
                source_ref,
                content_digest,
                observed_at,
                reported_agent_session_id,
                idempotency_key,
                reported_constitution_version,
            } => {
                push_field(bytes, task_id.as_bytes());
                push_field(bytes, &evidence_kind.to_be_bytes());
                push_field(bytes, source_ref.as_bytes());
                push_field(bytes, content_digest);
                push_field(bytes, observed_at.as_bytes());
                push_field(bytes, reported_agent_session_id.as_bytes());
                push_field(bytes, idempotency_key.as_bytes());
                push_field(bytes, reported_constitution_version.as_bytes());
            }
            Self::List {
                task_id,
                limit,
                page_before_recorded_at,
                page_before_evidence_id,
            } => {
                push_field(bytes, task_id.as_bytes());
                push_field(bytes, &limit.to_be_bytes());
                push_field(bytes, page_before_recorded_at.unwrap_or("").as_bytes());
                push_field(bytes, page_before_evidence_id.unwrap_or("").as_bytes());
            }
            Self::RecordConformance {
                task_id,
                evidence_id,
                verdict,
                finding_count,
                findings_digest,
                finding_codes,
                reported_checked_at,
                idempotency_key,
                reported_constitution_version,
            } => {
                push_field(bytes, task_id.as_bytes());
                push_field(bytes, evidence_id.as_bytes());
                push_field(bytes, &verdict.to_be_bytes());
                push_field(bytes, &finding_count.to_be_bytes());
                push_field(bytes, findings_digest);
                push_i32_list(bytes, finding_codes);
                push_field(bytes, reported_checked_at.as_bytes());
                push_field(bytes, idempotency_key.as_bytes());
                push_field(bytes, reported_constitution_version.as_bytes());
            }
            Self::ListConformance {
                task_id,
                limit,
                page_before_recorded_at,
                page_before_conformance_id,
            } => {
                push_field(bytes, task_id.as_bytes());
                push_field(bytes, &limit.to_be_bytes());
                push_field(bytes, page_before_recorded_at.unwrap_or("").as_bytes());
                push_field(bytes, page_before_conformance_id.unwrap_or("").as_bytes());
            }
        }
    }
}

fn push_i32_list(bytes: &mut Vec<u8>, items: &[i32]) {
    let count = u32::try_from(items.len()).unwrap_or(u32::MAX);
    push_field(bytes, &count.to_be_bytes());
    for item in items {
        push_field(bytes, &item.to_be_bytes());
    }
}

/// Binds an EvidenceAuthentication to one tenant, repository, and exact
/// operation. Every field is length-delimited so changing one field cannot
/// alter how another is parsed.
pub fn evidence_signing_bytes(
    tenant_id: &str,
    repository_id: &str,
    operation: &EvidenceOperation,
    authentication: &v1::EvidenceAuthentication,
) -> Vec<u8> {
    let identity_fields: [&[u8]; 6] = [
        authentication.signing_key_id.as_bytes(),
        authentication.node_id.as_bytes(),
        authentication.signed_at.as_bytes(),
        &authentication.nonce,
        tenant_id.as_bytes(),
        repository_id.as_bytes(),
    ];

    let mut bytes = Vec::with_capacity(EVIDENCE_DOMAIN.len() + 128);
    bytes.extend_from_slice(EVIDENCE_DOMAIN);
    for field in identity_fields {
        push_field(&mut bytes, field);
    }
    operation.push_fields(&mut bytes);
    bytes
}

#[cfg(test)]
mod tests {
    use super::*;

    fn authentication(nonce: u8) -> v1::EvidenceAuthentication {
        v1::EvidenceAuthentication {
            signing_key_id: "key-1".to_string(),
            node_id: "node-1".to_string(),
            signed_at: "2026-01-01T00:00:00Z".to_string(),
            nonce: vec![nonce; 16],
            signature: Vec::new(),
        }
    }

    const RECORD: EvidenceOperation<'static> = EvidenceOperation::Record {
        task_id: "task:123",
        evidence_kind: 1,
        source_ref: "commit:0123456789abcdef",
        content_digest: b"01234567890123456789012345678901",
        observed_at: "2026-01-01T00:00:00Z",
        reported_agent_session_id: "session:v1:agent",
        idempotency_key: "evidence:123",
        reported_constitution_version: "constitution:v4",
    };

    const CONFORMANCE: EvidenceOperation<'static> = EvidenceOperation::RecordConformance {
        task_id: "task:123",
        evidence_id: "evidence:123",
        verdict: 1,
        finding_count: 2,
        findings_digest: b"01234567890123456789012345678901",
        finding_codes: &[4, 7],
        reported_checked_at: "2026-01-01T00:00:00Z",
        idempotency_key: "conformance:123",
        reported_constitution_version: "constitution:v4",
    };

    #[test]
    fn identical_inputs_produce_identical_bytes() {
        let first = evidence_signing_bytes("tenant-a", "repo-a", &RECORD, &authentication(1));
        let second = evidence_signing_bytes("tenant-a", "repo-a", &RECORD, &authentication(1));

        assert_eq!(first, second);
    }

    #[test]
    fn record_and_list_never_share_a_signature_shape() {
        let record = evidence_signing_bytes("tenant-a", "repo-a", &RECORD, &authentication(1));
        let list = evidence_signing_bytes(
            "tenant-a",
            "repo-a",
            &EvidenceOperation::List {
                task_id: "task:123",
                limit: 20,
                page_before_recorded_at: None,
                page_before_evidence_id: None,
            },
            &authentication(1),
        );

        assert_ne!(record, list);
    }

    #[test]
    fn conformance_record_binds_its_outcome_and_never_shares_record_bytes() {
        let original =
            evidence_signing_bytes("tenant-a", "repo-a", &CONFORMANCE, &authentication(1));
        let changed_verdict = EvidenceOperation::RecordConformance {
            task_id: "task:123",
            evidence_id: "evidence:123",
            verdict: 3,
            finding_count: 2,
            findings_digest: b"01234567890123456789012345678901",
            finding_codes: &[4, 7],
            reported_checked_at: "2026-01-01T00:00:00Z",
            idempotency_key: "conformance:123",
            reported_constitution_version: "constitution:v4",
        };
        let changed_findings = EvidenceOperation::RecordConformance {
            task_id: "task:123",
            evidence_id: "evidence:123",
            verdict: 1,
            finding_count: 3,
            findings_digest: b"11234567890123456789012345678901",
            finding_codes: &[4, 7],
            reported_checked_at: "2026-01-01T00:00:00Z",
            idempotency_key: "conformance:123",
            reported_constitution_version: "constitution:v4",
        };

        assert_ne!(
            original,
            evidence_signing_bytes("tenant-a", "repo-a", &changed_verdict, &authentication(1))
        );
        assert_ne!(
            original,
            evidence_signing_bytes("tenant-a", "repo-a", &changed_findings, &authentication(1))
        );
        assert_ne!(
            original,
            evidence_signing_bytes("tenant-a", "repo-a", &RECORD, &authentication(1))
        );
    }

    #[test]
    fn conformance_list_never_shares_a_record_or_evidence_list_signature() {
        let conformance_list = evidence_signing_bytes(
            "tenant-a",
            "repo-a",
            &EvidenceOperation::ListConformance {
                task_id: "task:123",
                limit: 20,
                page_before_recorded_at: None,
                page_before_conformance_id: None,
            },
            &authentication(1),
        );
        let evidence_list = evidence_signing_bytes(
            "tenant-a",
            "repo-a",
            &EvidenceOperation::List {
                task_id: "task:123",
                limit: 20,
                page_before_recorded_at: None,
                page_before_evidence_id: None,
            },
            &authentication(1),
        );

        assert_ne!(conformance_list, evidence_list);
        assert_ne!(
            conformance_list,
            evidence_signing_bytes("tenant-a", "repo-a", &CONFORMANCE, &authentication(1))
        );
    }

    #[test]
    fn list_cursor_and_idempotency_keys_change_signed_bytes() {
        let first_evidence_page = EvidenceOperation::List {
            task_id: "task:123",
            limit: 20,
            page_before_recorded_at: None,
            page_before_evidence_id: None,
        };
        let next_evidence_page = EvidenceOperation::List {
            task_id: "task:123",
            limit: 20,
            page_before_recorded_at: Some("2026-01-01T00:00:00Z"),
            page_before_evidence_id: Some("evidence:123"),
        };
        let different_idempotency_key = EvidenceOperation::RecordConformance {
            task_id: "task:123",
            evidence_id: "evidence:123",
            verdict: 1,
            finding_count: 2,
            findings_digest: b"01234567890123456789012345678901",
            finding_codes: &[4, 7],
            reported_checked_at: "2026-01-01T00:00:00Z",
            idempotency_key: "conformance:other",
            reported_constitution_version: "constitution:v4",
        };
        let different_evidence_idempotency_key = EvidenceOperation::Record {
            task_id: "task:123",
            evidence_kind: 1,
            source_ref: "commit:0123456789abcdef",
            content_digest: b"01234567890123456789012345678901",
            observed_at: "2026-01-01T00:00:00Z",
            reported_agent_session_id: "session:v1:agent",
            idempotency_key: "evidence:other",
            reported_constitution_version: "constitution:v4",
        };

        assert_ne!(
            evidence_signing_bytes(
                "tenant-a",
                "repo-a",
                &first_evidence_page,
                &authentication(1)
            ),
            evidence_signing_bytes(
                "tenant-a",
                "repo-a",
                &next_evidence_page,
                &authentication(1)
            )
        );
        assert_ne!(
            evidence_signing_bytes("tenant-a", "repo-a", &CONFORMANCE, &authentication(1)),
            evidence_signing_bytes(
                "tenant-a",
                "repo-a",
                &different_idempotency_key,
                &authentication(1)
            )
        );
        assert_ne!(
            evidence_signing_bytes("tenant-a", "repo-a", &RECORD, &authentication(1)),
            evidence_signing_bytes(
                "tenant-a",
                "repo-a",
                &different_evidence_idempotency_key,
                &authentication(1)
            )
        );
        let different_constitution_version = EvidenceOperation::RecordConformance {
            task_id: "task:123",
            evidence_id: "evidence:123",
            verdict: 1,
            finding_count: 2,
            findings_digest: b"01234567890123456789012345678901",
            finding_codes: &[4, 7],
            reported_checked_at: "2026-01-01T00:00:00Z",
            idempotency_key: "conformance:123",
            reported_constitution_version: "constitution:v5",
        };
        assert_ne!(
            evidence_signing_bytes("tenant-a", "repo-a", &CONFORMANCE, &authentication(1)),
            evidence_signing_bytes(
                "tenant-a",
                "repo-a",
                &different_constitution_version,
                &authentication(1)
            )
        );
        let different_finding_codes = EvidenceOperation::RecordConformance {
            task_id: "task:123",
            evidence_id: "evidence:123",
            verdict: 1,
            finding_count: 2,
            findings_digest: b"01234567890123456789012345678901",
            finding_codes: &[5, 7],
            reported_checked_at: "2026-01-01T00:00:00Z",
            idempotency_key: "conformance:123",
            reported_constitution_version: "constitution:v4",
        };
        assert_ne!(
            evidence_signing_bytes("tenant-a", "repo-a", &CONFORMANCE, &authentication(1)),
            evidence_signing_bytes(
                "tenant-a",
                "repo-a",
                &different_finding_codes,
                &authentication(1)
            )
        );
    }

    #[test]
    fn changing_a_digest_or_task_changes_record_bytes() {
        let original = evidence_signing_bytes("tenant-a", "repo-a", &RECORD, &authentication(1));
        let changed_digest = EvidenceOperation::Record {
            task_id: "task:123",
            evidence_kind: 1,
            source_ref: "commit:0123456789abcdef",
            content_digest: b"11234567890123456789012345678901",
            observed_at: "2026-01-01T00:00:00Z",
            reported_agent_session_id: "session:v1:agent",
            idempotency_key: "evidence:123",
            reported_constitution_version: "constitution:v4",
        };
        let changed_task = EvidenceOperation::Record {
            task_id: "task:456",
            evidence_kind: 1,
            source_ref: "commit:0123456789abcdef",
            content_digest: b"01234567890123456789012345678901",
            observed_at: "2026-01-01T00:00:00Z",
            reported_agent_session_id: "session:v1:agent",
            idempotency_key: "evidence:123",
            reported_constitution_version: "constitution:v4",
        };

        assert_ne!(
            original,
            evidence_signing_bytes("tenant-a", "repo-a", &changed_digest, &authentication(1))
        );
        assert_ne!(
            original,
            evidence_signing_bytes("tenant-a", "repo-a", &changed_task, &authentication(1))
        );
    }

    #[test]
    fn evidence_domain_never_shares_claim_domain_bytes() {
        let bytes = evidence_signing_bytes("tenant-a", "repo-a", &RECORD, &authentication(1));

        assert!(bytes.starts_with(EVIDENCE_DOMAIN));
        assert_ne!(EVIDENCE_DOMAIN, crate::claim_auth::CLAIM_DOMAIN);
    }
}
